import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  compact: boolean;
  font: string;
}

export interface AppearanceSettingsScreenProps {
  value?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEMES: { value: ThemeValue; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS = [
  { value: 'sans', label: 'Без засечек', meta: 'По умолчанию' },
  { value: 'display', label: 'Акцидентный' },
  { value: 'mono', label: 'Монопространственный' },
];

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  compact: false,
  font: 'sans',
};

export default function AppearanceSettingsScreen({
  value,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>(value ?? DEFAULTS);
  const current = value ?? settings;

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...current, ...patch };
    setSettings(next);
    onChange?.(next);
  };

  const themeLabel =
    THEMES.find((item) => item.value === current.theme)?.label ?? 'Системная';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 520,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        color: 'var(--jx-text)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 16,
          flexWrap: 'wrap',
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          <h2
            style={{
              margin: 0,
              fontFamily: 'var(--jx-font-display)',
              fontSize: 20,
              color: 'var(--jx-text)',
            }}
          >
            Внешний вид
          </h2>
          <p style={{ margin: 0, fontSize: 13, color: 'var(--jx-text-2)' }}>
            Настройки применяются сразу и сохраняются для этого устройства.
          </p>
        </div>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          <span style={{ fontSize: 13, color: 'var(--jx-text-2)' }}>Тема</span>
          <JxToggle
            items={THEMES}
            value={current.theme}
            onValueChange={(next) => update({ theme: next as ThemeValue })}
          />
        </div>

        <JxSlider
          label="Масштаб интерфейса"
          min={80}
          max={140}
          step={10}
          unit="%"
          showOutput
          value={current.scale}
          onValueChange={(next) => update({ scale: next })}
        />

        <JxSwitch
          label="Плотная вёрстка"
          checked={current.compact}
          onChange={(event) => update({ compact: event.target.checked })}
        />
      </div>

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={FONTS}
        value={current.font}
        onValueChange={(next) => update({ font: next })}
      />
    </section>
  );
}

